-- Full tour pages + detailed itineraries for the cultural tours that were card-only. Idempotent: re-running replaces these tours' itineraries.
-- Run locally with: npm run db:cultural-pages:local   (remote: wrangler d1 execute altara-db --remote --file=seed-cultural-pages.sql)

UPDATE tours SET has_page = 1, summary = 'Seven days timed around a tsechu — Bhutan’s great masked dance festivals — with front-row seating, a guide who explains every dance, and quiet valley days either side.', overview_title = 'Tour Overview', overview = 'A tsechu is the beating heart of Bhutanese life: for two or three days a dzong courtyard fills with monks in brocade and masks, villagers in their finest kira and gho, and the old stories of Guru Rinpoche are danced out in front of you. This journey is built around one of those festivals, so you arrive in the right valley a day early, settle in, and watch it from a good seat rather than the back of the crowd.

The days around the festival are slower and more private — a drive over Dochula pass, the great dzong at Punakha, a farmhouse lunch — so the festival is a high point in a journey and not the whole of it. Festival dates follow the lunar calendar and change every year, so we shape the route to the tsechu you choose. See our [festival calendar](/festival-tours) for the current dates.', highlights = '["Front-row seating at a tsechu in a dzong courtyard","A guide who explains the meaning of each mask dance","Dress in a gho or kira and join the crowd for the festival","Cross Dochula pass and visit Punakha Dzong","A blessing from the great thongdrol (unfurled at dawn on the last day, where scheduled)","Quiet valley days in Paro before and after"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu, Punakha"},{"icon":"sun","label":"Best Season","value":"Festival dates vary — mostly Sept–Nov and Mar–Apr"},{"icon":"mountain","label":"Max Altitude","value":"3,100m — Dochula Pass"},{"icon":"bag","label":"Accommodation","value":"Your choice — boutique to luxury"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV or luxury travel van"}]', facts_note = 'Use this as a general guide to the tour. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack For A Festival', pack_text = 'Festival days are long, mostly outdoors and often sunny at altitude, so bring a hat, sunglasses and sunscreen, plus a light jacket for early mornings and evenings. Comfortable shoes you can sit in all day matter more than anything else.

We can arrange a gho or kira for you to wear to the festival — ask when you enquire. Bring a camera with a zoom lens; guides will tell you where photography is welcome.', inclusions = '["Accommodation, from boutique to luxury, to suit your budget","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Personal expenses, drinks and gratuities"]', faqs = '[{"question":"Which tsechu will we attend?","answer":"The big festivals fall in spring and autumn. Tell us your travel month and we will suggest the tsechu that suits it. Dates change every year — see the [festival calendar](/festival-tours)."},{"question":"Do we need to book early for a festival?","answer":"Yes. Festival weeks are the busiest of the year for hotels and guides, so we recommend enquiring several months ahead."},{"question":"Is photography allowed at the festival?","answer":"Generally yes in the courtyard, but not inside temples or during certain sacred rites. Your guide will tell you what is appropriate on the day."}]', districts = '["Paro","Thimphu","Punakha"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Seven days timed around a tsechu — Bhutan’s great masked dance festivals — with front-row seating, a guide who explains every dance, and quiet valley days either side.', updated_at = datetime('now') WHERE slug = 'tsechu-festival-journey';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'tsechu-festival-journey');

UPDATE tours SET has_page = 1, summary = 'Six days across the Black Mountains to Bumthang, Bhutan’s spiritual heartland — ancient temples, a burning lake and the Tang and Ura valleys.', overview_title = 'Tour Overview', overview = 'Bumthang is where Buddhism took root in Bhutan. Its four valleys hold some of the country''s oldest temples, many linked to Guru Rinpoche and the treasure-finder Pema Lingpa, and the pace of life is gentler than in the west. This journey crosses the Black Mountains to get there, so the drive itself — high passes, rhododendron forest, a fortress at Trongsa — is part of the trip.

Once in Bumthang, days are built around its sacred places: Jambay Lhakhang, Kurjey Lhakhang, Tamshing Lhakhang and Membartsho, the Burning Lake. You spend time with monks, taste local buckwheat pancakes and cheese, and walk through farming villages that still keep to their old rhythms.', highlights = '["Cross Pele La and Yotong La, the high passes of central Bhutan","Trongsa Dzong, the fortress that guards the country’s heartland","Jambay, Kurjey and Tamshing — three of Bhutan’s oldest temples","Membartsho, the Burning Lake, a sacred pool of Pema Lingpa","Walk through Ura or Tang valley farming villages","Local buckwheat pancakes, cheese and honey tasted at the source"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu, Trongsa, Bumthang"},{"icon":"sun","label":"Best Season","value":"March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"3,425m — Yotong La Pass"},{"icon":"bag","label":"Accommodation","value":"Your choice — boutique to luxury"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV or luxury travel van"}]', facts_note = 'Use this as a general guide to the tour. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack For Bumthang', pack_text = 'Bumthang sits at around 2,600 metres and evenings are cold even in spring and autumn, so bring warm layers, a windproof jacket and a hat. Winter visitors will want a proper down coat.

Bring comfortable walking shoes for temple courtyards and village paths, a small daypack, and a torch for dimly lit temple interiors.', inclusions = '["Accommodation, from boutique to luxury, to suit your budget","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Personal expenses, drinks and gratuities","Domestic flights, if used instead of the road, which are quoted separately"]', faqs = '[{"question":"How long are the drives?","answer":"Two of the days involve long mountain drives of six to seven hours with plenty of stops. Your driver and guide pace them with viewpoints, tea and lunch breaks."},{"question":"Can we fly instead of driving?","answer":"There are domestic flights between Paro and Bumthang that save a long drive, subject to schedule and weather. We will quote either option when you enquire."},{"question":"Is the trip physically demanding?","answer":"No. The days are mostly drives, temple visits and short walks. Anyone comfortable on mountain roads can do it."}]', districts = '["Paro","Thimphu","Punakha","Wangdue Phodrang","Trongsa","Bumthang"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Six days across the Black Mountains to Bumthang, Bhutan’s spiritual heartland — ancient temples, a burning lake and the Tang and Ura valleys.', updated_at = datetime('now') WHERE slug = 'bumthang-spiritual-trail';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'bumthang-spiritual-trail');

UPDATE tours SET has_page = 1, summary = 'Four days of Bhutanese craft and village life — weavers, a farmhouse, a living folk museum and a textile academy — in the Thimphu, Punakha and Paro valleys.', overview_title = 'Tour Overview', overview = 'Everything a Bhutanese person wears or lives with has a story: the kira woven over months on a backstrap loom, the butter lamp, the sharp red chilli on the roof. This short journey puts you inside those stories, in the places where they are still being made.

In Thimphu you visit the Royal Textile Academy and the Folk Heritage Museum, in Punakha you walk through the fields of the Chimi Lhakhang village, and in Paro you spend an afternoon in a working farmhouse. It is a good first trip for travellers who care more about people and craft than about checking off monuments.', highlights = '["Royal Textile Academy, home of Bhutan’s weaving tradition","See a weaver at her loom in a village home","Folk Heritage Museum — a rural house preserved as it was lived in","Walk through paddy fields to Chimi Lhakhang","A traditional farmhouse lunch and hot stone bath","Try your hand at archery, the national sport"]', facts = '[{"icon":"pin","label":"Destinations","value":"Thimphu, Punakha, Paro"},{"icon":"sun","label":"Best Season","value":"All year; best March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"3,100m — Dochula Pass"},{"icon":"bag","label":"Accommodation","value":"Your choice — boutique to luxury"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV or luxury travel van"}]', facts_note = 'Use this as a general guide to the tour. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack For Village Days', pack_text = 'Bring clothes that are modest and easy to move in — shoulders and knees covered for temples and homes — plus walking shoes you can slip off at doorways.

A small gift from home, such as postcards or fruit, goes down well when you are invited into a house; ask your guide what is appropriate.', inclusions = '["Accommodation, from boutique to luxury, to suit your budget","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Personal expenses, drinks and gratuities"]', faqs = '[{"question":"Can we buy textiles directly from weavers?","answer":"Yes. Your guide will introduce you to weavers and shops that sell genuine handwoven pieces, which take months to make and are priced accordingly."},{"question":"Is this suitable for families?","answer":"Very. There is little hiking, plenty of hands-on moments and a farmhouse visit that children usually remember."},{"question":"Can this be extended?","answer":"Easily. Many guests add a Tiger’s Nest hike or extra nights in Punakha. Tell us what you have in mind."}]', districts = '["Thimphu","Punakha","Paro"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Four days of Bhutanese craft and village life — weavers, a farmhouse, a living folk museum and a textile academy — in the Thimphu, Punakha and Paro valleys.', updated_at = datetime('now') WHERE slug = 'weaving-village-life';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'weaving-village-life');

UPDATE tours SET has_page = 1, summary = 'Nine days to Bhutan’s far east — Bumthang, Mongar, Lhuentse’s Khoma weaving village and Trashigang — where the culture feels least changed.', overview_title = 'Tour Overview', overview = 'Eastern Bhutan is the part of the country that most visitors never see. The roads are long and the hotels are simple, but the reward is a Bhutan that has changed very little: weaving villages, hill-top dzongs and monasteries with no one else around. This journey follows the old route east through Bumthang, Mongar and Lhuentse to Trashigang and Trashi Yangtse.

It is a journey for travellers who like roads as much as destinations. You cross the Thrumshing La pass, visit Khoma, famous for its brocade kiras, and meet people who still weave, farm and herd as their grandparents did. We pace the drives, add comfort where we can, and keep days flexible so the east can surprise you.', highlights = '["Cross Thrumshing La, the highest pass on the national highway","Khoma village — the heart of Bhutanese brocade weaving","Lhuentse Dzong, perched above a river gorge","Trashigang Dzong and its market, a meeting place for hill peoples","Chorten Kora and Trashi Yangtse’s woodworkers","Eastern hospitality: ara, butter tea and village homes"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu, Trongsa, Bumthang, Mongar, Lhuentse, Trashigang, Trashi Yangtse"},{"icon":"sun","label":"Best Season","value":"March–May & October–November"},{"icon":"mountain","label":"Max Altitude","value":"3,780m — Thrumshing La Pass"},{"icon":"bag","label":"Accommodation","value":"Hotels and simple lodges; boutique where available"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV or luxury travel van"}]', facts_note = 'Use this as a general guide to the tour. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack For The East', pack_text = 'The east has a wide range of altitudes and climates, so pack in layers: warm clothes for the high passes and light ones for the low, warm valleys. A good rain jacket is useful all year.

Bring a torch, insect repellent for the lower valleys, and any medication you need — pharmacies are few and far between. Motion-sickness tablets are worth packing for the long mountain roads.', inclusions = '["Accommodation, from boutique to luxury, to suit your budget","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Personal expenses, drinks and gratuities","Domestic flights, if used, which are quoted separately"]', faqs = '[{"question":"How comfortable is the accommodation?","answer":"Good hotels in the larger towns, simpler lodges in smaller ones. We choose the best available each night and will tell you honestly what to expect."},{"question":"Are the roads rough?","answer":"The national highway is paved but winding, with some slower stretches. Plan on long days in the vehicle with frequent stops."},{"question":"How do we get back west?","answer":"Either a domestic flight from Yonphula to Paro (subject to schedule and weather) or an extended drive. We confirm the best option when planning."}]', districts = '["Paro","Thimphu","Wangdue Phodrang","Trongsa","Bumthang","Monggar","Lhuentse","Trashigang","Trashi Yangtse"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Nine days to Bhutan’s far east — Bumthang, Mongar, Lhuentse’s Khoma weaving village and Trashigang — where the culture feels least changed.', updated_at = datetime('now') WHERE slug = 'eastern-bhutan-heritage';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage');

UPDATE tours SET has_page = 1, summary = 'Three days in Thimphu, the world’s only capital without traffic lights — royal heritage, dzong life and a city where tradition and modern Bhutan meet.', overview_title = 'Tour Overview', overview = 'Thimphu is unlike any other capital: no traffic lights, a skyline of dzongs and temples, and a king who still presides over the country’s great festivals. This short journey is for travellers with only a few days who want to understand how modern Bhutan works — where the government sits, where monks and civil servants share a courtyard, where a national library holds ancient manuscripts and a weekend market sells red rice and cheese.

We keep it unhurried: a late-afternoon walk, a long lunch, an evening at a monastery above the city. It also pairs well with a hike to Tiger''s Nest or a few extra nights in Punakha.', highlights = '["Tashichho Dzong, seat of the government and the monk body","Buddha Dordenma, a huge golden Buddha overlooking the valley","National Library and Royal Textile Academy","The weekend market, where farmers come down from the hills","Changangkha Lhakhang above the city","A hot stone bath and farmhouse dinner (optional)"]', facts = '[{"icon":"pin","label":"Destinations","value":"Thimphu, Paro"},{"icon":"sun","label":"Best Season","value":"All year; best March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"2,320m — Thimphu"},{"icon":"bag","label":"Accommodation","value":"Your choice — boutique to luxury"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV or luxury travel van"}]', facts_note = 'Use this as a general guide to the tour. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack For The Capital', pack_text = 'Thimphu is smart-casual: shoulders and knees covered for dzongs and temples, and shoes that are easy to slip off. Evenings are cool for most of the year, so bring a light jacket or sweater.

Carry a small bag for photographs and a camera with extra memory — there is plenty to photograph, and some places ask for no photos inside.', inclusions = '["Accommodation, from boutique to luxury, to suit your budget","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Personal expenses, drinks and gratuities"]', faqs = '[{"question":"Is three days enough for Thimphu?","answer":"It is a good introduction. The capital is compact, and three days lets you see its main sights without rushing and still leave time for a quiet evening."},{"question":"Can I see the Tashichho Dzong?","answer":"The dzong is open to visitors in the late afternoon and evening, when the offices close. Your guide will time your visit accordingly."},{"question":"Can we add the Tiger’s Nest hike?","answer":"Yes. Many guests add a day in Paro. See our [Tiger’s Nest Pilgrimage](/tours/tigers-nest-pilgrimage) for the full route."}]', districts = '["Thimphu","Paro"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Three days in Thimphu, the world’s only capital without traffic lights — royal heritage, dzong life and a city where tradition and modern Bhutan meet.', updated_at = datetime('now') WHERE slug = 'royal-capital-immersion';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'royal-capital-immersion');
