INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'tsechu-festival-journey'), 1, 'Arrive In Paro, Drive To Thimphu', 'The first gift from Bhutan is the cool, clean air as you step off the plane. After visa formalities you are welcomed in the traditional way and drive on to the capital, where you settle in before the festival.', '54 km / 1 to 1.5 hrs', '2,320m / 7,611ft', '["Welcome by your guide at Paro airport","Memorial Chorten","Evening walk in Thimphu town"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'tsechu-festival-journey'), 2, 'Tsechu Festival, Day One', 'A day inside the festival courtyard at Tashichho Dzong. Your guide explains the masked dances — the Dance of the Black Hats, the Stag Dance and others — and the stories behind them, with breaks for tea and a long lunch.', 'Local — 10 mins', '2,320m / 7,611ft', '["Tsechu masked dances at the dzong","Reserved seating with your guide","Local lunch among festival crowds"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'tsechu-festival-journey'), 3, 'Over Dochula Pass To Punakha', 'Climb out of Thimphu to Dochula pass and its 108 memorial chortens, with Himalayan views on a clear morning, then descend through rhododendron forest into the warm Punakha valley.', '77 km / 2.5 to 3 hrs', 'Dochula 3,100m / 10,171ft; Punakha 1,200m / 3,937ft', '["Dochula Pass and the 108 Druk Wangyal Chortens","Chimi Lhakhang, the temple of fertility","Punakha Dzong at sunset"]', 'Overnight at the hotel in Punakha');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'tsechu-festival-journey'), 4, 'Punakha Dzong And Return To Paro', 'Walk across the cantilever bridge to Punakha Dzong at the meeting of two rivers, then drive back over the pass to Paro.', '125 km / 4 to 4.5 hrs', 'Paro 2,200m / 7,218ft', '["Punakha Dzong","Walk across the Punakha suspension bridge","Dochula Pass on the return"]', 'Overnight at the hotel in Paro');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'tsechu-festival-journey'), 5, 'Paro Tsechu', 'Spend the day at the Paro festival in the courtyard of Rinpung Dzong, ending the morning with a quiet look at the unfurled sacred banner where it is shown.', 'Local — 10 mins', '2,200m / 7,218ft', '["Paro tsechu at Rinpung Dzong","The thongdrol blessing (on festival’s final morning, where scheduled)","Walk across the old Nyamai Zam bridge"]', 'Overnight at the hotel in Paro');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'tsechu-festival-journey'), 6, 'A Slow Day In Paro Valley', 'A quieter day with time to rest: the National Museum at Ta Dzong, the 7th-century Kyichu Lhakhang and a traditional farmhouse lunch.', 'Local — under 30 mins between stops', '2,200m / 7,218ft', '["National Museum at Ta Dzong","Kyichu Lhakhang","Farmhouse lunch with a hot stone bath (optional)"]', 'Overnight at the hotel in Paro');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'tsechu-festival-journey'), 7, 'Departure', 'A relaxed morning before your private transfer to Paro International Airport for your onward flight.', 'Hotel to airport: 15 mins', '2,235m / 7,333ft', '["Private transfer to Paro International Airport"]', '');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumthang-spiritual-trail'), 1, 'Arrive In Paro, Drive To Thimphu', 'The first gift from Bhutan will be the cool, clean air as you step out of the plane. After your visa formalities you are welcomed in the traditional way and drive on to Thimphu.', '54 km / 1 to 1.5 hrs', '2,320m / 7,611ft', '["Memorial Chorten","Explore Thimphu town"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumthang-spiritual-trail'), 2, 'Thimphu To Trongsa', 'A long, rewarding day across the country: over Dochula, through Wangdue Phodrang and up to Pele La, the pass that separates western and central Bhutan, before dropping to Trongsa.', '190 km / 6 to 7 hrs', 'Pele La 3,420m / 11,220ft; Trongsa 2,200m / 7,218ft', '["Dochula Pass","Pele La Pass","Chendebji Chorten, built in the Nepalese style"]', 'Overnight at the hotel in Trongsa');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumthang-spiritual-trail'), 3, 'Trongsa To Bumthang', 'Begin at Trongsa Dzong, once the seat of the royal family’s power, then cross Yotong La and descend into the first of Bumthang’s four valleys.', '68 km / 2.5 to 3 hrs', 'Yotong La 3,425m / 11,237ft; Jakar 2,600m / 8,530ft', '["Trongsa Dzong","Ta Dzong tower museum","Yotong La Pass","Chumey valley weaving village"]', 'Overnight at the hotel in Bumthang');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumthang-spiritual-trail'), 4, 'The Sacred Sites Of Bumthang', 'A full day among the valley’s great temples. Pause for a blessing from resident monks and taste local pancakes, cheese and honey.', 'Local — under 30 mins between stops', '2,600m / 8,530ft', '["Jambay Lhakhang","Kurjey Lhakhang","Tamshing Lhakhang","Membartsho, the Burning Lake","Jakar Dzong"]', 'Overnight at the hotel in Bumthang');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumthang-spiritual-trail'), 5, 'Ura Valley And Village Life', 'Drive up to the Ura valley, a high pasture of white-washed houses and yak herders, and spend the afternoon on an easy village walk and visit to a family home.', '48 km / 1.5 to 2 hrs return', 'Ura 3,100m / 10,171ft', '["Shingkhar Rabdey in Ura","Village walk and a family tea","Optional visit to a cheese or honey maker"]', 'Overnight at the hotel in Bumthang');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'bumthang-spiritual-trail'), 6, 'Return To Paro And Departure', 'Return west by road or domestic flight depending on schedules and weather, with a private transfer to Paro International Airport.', 'By flight: about 35 mins; by road: 2 days', 'Paro 2,235m / 7,333ft', '["Domestic flight or road transfer to Paro","Private transfer to the airport"]', '');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'weaving-village-life'), 1, 'Arrive In Paro, Drive To Thimphu', 'After a warm welcome at Paro airport you drive to Thimphu and settle in. If time allows, visit the weekend-market area or take an early evening walk through the town.', '54 km / 1 to 1.5 hrs', '2,320m / 7,611ft', '["Welcome at Paro airport","Memorial Chorten","Evening in Thimphu town"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'weaving-village-life'), 2, 'Textiles And Heritage In Thimphu', 'A day in the capital among craft and tradition: the weavers’ galleries, a farmhouse preserved as a museum and the artisans who keep the thirteen traditional arts alive.', 'Local — under 20 mins between stops', '2,320m / 7,611ft', '["Royal Textile Academy","Folk Heritage Museum","Institute for Zorig Chusum (the thirteen traditional arts)","Handicrafts emporium"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'weaving-village-life'), 3, 'Thimphu To Punakha', 'Cross Dochula pass to the warm Punakha valley, walk through fields to Chimi Lhakhang and visit a village family before seeing Punakha Dzong in the afternoon light.', '77 km / 2.5 to 3 hrs', 'Dochula 3,100m / 10,171ft; Punakha 1,200m / 3,937ft', '["Dochula Pass","Walk to Chimi Lhakhang through paddy fields","Punakha Dzong","Village home visit"]', 'Overnight at the hotel in Punakha');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'weaving-village-life'), 4, 'Punakha To Paro And Departure', 'A farmhouse lunch and a few last hours in Paro before your transfer to the airport for your onward flight.', '125 km / 4 to 4.5 hrs', 'Paro 2,200m / 7,218ft', '["Farmhouse lunch with a local family","Archery lesson","Private transfer to Paro International Airport"]', '');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 1, 'Arrive In Paro, Drive To Thimphu', 'Your journey begins with a warm welcome at Paro airport and a drive to the capital, where you rest before the long road east.', '54 km / 1 to 1.5 hrs', '2,320m / 7,611ft', '["Welcome at Paro airport","Memorial Chorten","Thimphu town"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 2, 'Thimphu To Trongsa', 'Cross Dochula and Pele La into central Bhutan, with stops at viewpoints and Chendebji Chorten along the way.', '190 km / 6 to 7 hrs', 'Pele La 3,420m / 11,220ft; Trongsa 2,200m / 7,218ft', '["Dochula Pass","Pele La Pass","Chendebji Chorten","Trongsa town view of the dzong"]', 'Overnight at the hotel in Trongsa');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 3, 'Trongsa To Bumthang', 'Visit Trongsa Dzong in the morning, cross Yotong La and arrive in the Jakar valley for the afternoon.', '68 km / 2.5 to 3 hrs', 'Yotong La 3,425m / 11,237ft; Jakar 2,600m / 8,530ft', '["Trongsa Dzong","Ta Dzong tower museum","Yotong La Pass"]', 'Overnight at the hotel in Bumthang');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 4, 'A Day In Bumthang', 'Visit three of the valley’s oldest temples and the sacred pool of Membartsho, then rest before the next stage east.', 'Local — under 30 mins between stops', '2,600m / 8,530ft', '["Jambay Lhakhang","Kurjey Lhakhang","Tamshing Lhakhang","Membartsho, the Burning Lake"]', 'Overnight at the hotel in Bumthang');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 5, 'Bumthang To Mongar', 'The longest and most dramatic drive of the trip: over Ura La and Thrumshing La, through Thrumshing La National Park, and down to subtropical Mongar.', '195 km / 6 to 7 hrs', 'Thrumshing La 3,780m / 12,402ft; Mongar 1,600m / 5,249ft', '["Ura La Pass","Thrumshing La Pass and its rhododendron forest","Mongar town and dzong"]', 'Overnight at the hotel in Mongar');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 6, 'Mongar To Lhuentse And Khoma', 'A winding drive through the Kurichhu valley to Lhuentse, then on to Khoma, where women weave the brocade kiras that are Bhutan’s finest textiles.', '75 km / 3 to 3.5 hrs', 'Lhuentse 1,700m / 5,577ft', '["Lhuentse Dzong","Khoma weaving village and a weaver’s home","Optional visit to Gom Kora on the return route"]', 'Overnight at the hotel in Lhuentse');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 7, 'Lhuentse To Trashigang', 'Return along the valley and continue east to Trashigang, the largest town in the east, perched above the Drangme Chhu.', '150 km / 5 to 5.5 hrs', 'Trashigang 1,150m / 3,773ft', '["Gom Kora temple (en route)","Trashigang town and dzong view"]', 'Overnight at the hotel in Trashigang');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 8, 'Trashi Yangtse And Back', 'Take the road north to Trashi Yangtse to see Chorten Kora and the artisans who make the country’s carved wooden bowls, then return to Trashigang.', '55 km / 2 hrs each way', 'Trashi Yangtse 1,800m / 5,906ft', '["Chorten Kora","Dechen Phodrang monastery","Wooden bowl workshops"]', 'Overnight at the hotel in Trashigang');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'eastern-bhutan-heritage'), 9, 'Return West And Departure', 'Fly from Yonphula back to Paro, schedule and weather permitting (or begin the longer drive west), and transfer to the airport for your onward flight.', 'By flight: about 1 hr; by road: 3 days', 'Paro 2,235m / 7,333ft', '["Domestic flight or road journey west","Private transfer to Paro International Airport"]', '');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'royal-capital-immersion'), 1, 'Arrive In Paro, Drive To Thimphu', 'The first gift from Bhutan will be the cool, clean fresh air as you step out of the plane. After visa formalities we welcome you in a traditional way and drive on to Thimphu. Sightseeing depends on the flight timing.', '54 km / 1 to 1.5 hrs', '2,320m / 7,611ft', '["Memorial Chorten","Explore Thimphu town"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'royal-capital-immersion'), 2, 'A Day In The Capital', 'Spend a full day among Thimphu’s landmarks: the great golden Buddha, the national library, the textile museum and, in the late afternoon, Tashichho Dzong when it opens to visitors.', 'Local — under 20 mins between stops', '2,320m / 7,611ft', '["Buddha Dordenma","National Library","Royal Textile Academy","Changangkha Lhakhang","Tashichho Dzong in the evening"]', 'Overnight at the hotel in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'royal-capital-immersion'), 3, 'Thimphu To Paro And Departure', 'Visit the Centenary Farmers’ Market if it is the weekend, or the Folk Heritage Museum, then drive to Paro for your onward flight.', '54 km / 1 to 1.5 hrs', 'Paro 2,235m / 7,333ft', '["Centenary Farmers’ Market (weekends)","Folk Heritage Museum","Private transfer to Paro International Airport"]', '');
